            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            prerelease_identifiers = prerelease.split('.')

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # If one has pre-release and other doesn't
        if not pre1 and not pre2:
            return 0
        if not pre1:  # pre1 is empty, pre2 is not
            return 1  # version without pre-release sorts after
        if not pre2:  # pre2 is empty, pre1 is not
            return -1  # version with pre-release sorts before

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1, id2 = pre1[i], pre2[i]
            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both are all-digits, compare numerically
                val1, val2 = int(id1), int(id2)
                if val1 < val2:
                    return -1
                elif val1 > val2:
                    return 1
            elif is_digit1:  # id1 is all-digits, id2 is not
                return -1  # all-digit sorts before other
            elif is_digit2:  # id2 is all-digits, id1 is not
                return 1  # other sorts after all-digit
            else:
                # Both are non-digit, compare by ASCII
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # All shared identifiers are equal
        if len(pre1) < len(pre2):
            return -1  # Fewer identifiers sorts first
        elif len(pre1) > len(pre2):
            return 1
        else:
            return 0

    def sort_key(version):
        major, minor, patch, prerelease = parse_version(version)

        # Convert pre-release identifiers for sorting
        # We need a comparable key that respects the comparison rules
        prerelease_key = []
        if prerelease:
            for identifier in prerelease:
                if identifier.isdigit():
                    prerelease_key.append((0, int(identifier)))  # 0 prefix for numeric
                else:
                    prerelease_key.append((1, identifier))  # 1 prefix for string

        # For sorting: version without prerelease should come after same version with prerelease
        # So if no prerelease, we use a special marker that sorts after any prerelease
        if not prerelease:
            prerelease_key = [(2,)]  # Sorts after everything

        return (major, minor, patch, prerelease_key)

    # Sort with stable sort (preserving input order for equal precedence)
    indexed_versions = [(v, i) for i, v in enumerate(versions)]
    indexed_versions.sort(key=lambda x: (sort_key(x[0]), x[1]))

    return [v for v, _ in indexed_versions]

